-- -5 a todas las Dell (premium incluidas).
--
-- Llegaban demasiado arriba en el puntaje frente a Lenovo y HP. Se suma a la
-- resta de Latitude común (3000/5000), que queda en -15 en total.
-- scorePenalties de la fila es igual al del código (0043); se reemplaza entero
-- por el del código (generado, no tipeado a mano).

update public.search_config
   set config = jsonb_set(config, '{scorePenalties}', $j$[{"label":"Dell","pattern":"\\b(?:dell|latitude|precision|xps|inspiron|vostro|alienware)\\b","flags":"i","points":5,"scope":"title","ignoreNegated":false},{"label":"Dell Latitude","pattern":"\\blatitude\\b(?![\\s-]*(?:\\d{1,2}(?:\\.\\d)?\\s*(?:\"|”|''|in(?:ch)?|-inch)?\\s*)?e?[79]\\d{3}\\b)","flags":"i","points":10,"scope":"title","ignoreNegated":false},{"label":"Incluye cargador","pattern":"(?:\\b(?:includes?|including|included|comes\\s+with|ships\\s+with|with)\\b|w\\/|\\+)\\s*(?:(?:an?|the|original|oem|genuine)\\s+)*(?:ac\\s*|power\\s*)?(?:adapter|charger|power\\s*(?:supply|cord|cable))s?\\b|\\b(?:ac\\s*adapter|power\\s*adapter|charger|power\\s*supply|power\\s*cord)s?\\s*(?:is\\s*|are\\s*)?(?:[:\\-]\\s*)?(?:included|yes)\\b(?!\\s*[:\\-]?\\s*(?:no|not|n\\/a)\\b)","flags":"i","points":-5,"scope":"titleAndDescription","ignoreNegated":true,"ignoreContextPattern":"\\bif\\b|unless|\\bmay\\b|optional|sold\\s+separately|not\\s+included|purchase|available|upgrade|add-?on"},{"label":"Componente con falla","pattern":"\\b(?:ports?|usb(?:[\\s-]?[ac])?|webcam|camera|cam|speakers?|audio|sound|mic(?:rophone)?|bluetooth|wi-?fi|wireless|fingerprint|reader|touch\\s*screen|touchscreen|touch|trackpad|touchpad|mouse|clicks?|keys?|keyboard|backlight|stylus|pen|buttons?|jack|hdmi|ethernet|lan|sd|card|fan|led|lights?|sensor|nfc|sim|lte|wwan|display\\s*port|screws?|covers?|feet|foot|rubber|latch)\\b(?:[^.!?\\n|•]|\\.(?=\\d)){0,40}?\\b(?:not\\s*working|(?:does\\s*not|doesn'?t|won'?t)\\s*work|non[\\s-]?functional|inoperable)\\b","flags":"i","points":10,"scope":"titleAndDescription","ignoreNegated":true,"ignoreContextPattern":"return|refund|warrant|guarant|polic|listed\\s+as|label|exclud|exception|unless|\\bif\\b|\\bmay\\b|\\bshould\\b|buyer|grade[sd]?\\b|definition|not\\s+tested|untested|focus\\s+materials|\\bwe\\s+(?:will|do|are|can)|contact|as\\s+described"},{"label":"Declara daño","pattern":"\\b(?:dmg|damaged?)\\b","flags":"i","points":10,"scope":"titleAndDescription","ignoreNegated":true,"ignoreContextPattern":"ship|transit|package|parcel|carrier|\\bups\\b|fedex|usps|deliver|return|refund|claim|tamper|arriv|not as (?:described|shown)|warranty|misuse|abuse|accident|avoid|any signs of|materials recovery|sanitized|latches, hinges|used (?:excellent|fair|poor)|new open box"}]$j$::jsonb)
 where id = 1;
